package com.bank.hateoas.controller;

import com.bank.hateoas.dto.AccountResponse;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.hateoas.EntityModel;
import org.springframework.web.bind.annotation.*;
import java.math.BigDecimal;

import static org.springframework.hateoas.server.mvc.WebMvcLinkBuilder.*;

// FULL HATEOAS version (for evaluation): the response carries links to the
// next valid actions. Links are built from controller methods so they stay
// correct if routes change. Note the dynamic transition: a FROZEN account
// does NOT get a transfer link.
@RestController
@RequestMapping("/api/v1/accounts")
public class AccountHateoasController {

    private static final Logger log = LoggerFactory.getLogger(AccountHateoasController.class);

    @GetMapping("/{accountNumber}")
    public EntityModel<AccountResponse> get(@PathVariable String accountNumber) {
        AccountResponse dto = load(accountNumber);
        EntityModel<AccountResponse> model = EntityModel.of(dto);

        // self link — always present
        model.add(linkTo(methodOn(AccountHateoasController.class)
                .get(accountNumber)).withSelfRel());

        // related resource link
        model.add(linkTo(methodOn(TransactionController.class)
                .list(accountNumber, 0, 20)).withRel("transactions"));

        // DYNAMIC transition: only an ACTIVE account can transfer.
        if ("ACTIVE".equals(dto.getStatus())) {
            model.add(linkTo(methodOn(AccountHateoasController.class)
                    .get(accountNumber)).withRel("transfer"));
            log.info("Account {} ACTIVE → transfer link included", accountNumber);
        } else {
            log.info("Account {} {} → transfer link omitted", accountNumber, dto.getStatus());
        }
        return model;
    }

    private AccountResponse load(String accountNumber) {
        return new AccountResponse(accountNumber, new BigDecimal("1000000"), "ACTIVE");
    }
}
```

