package com.bank.hateoas.dto;

import java.util.List;
import java.util.Map;

// PRAGMATIC HATEOAS: the ONE place links clearly help — pagination. We carry
// next/prev links and skip the rest of the hypermedia machinery.
public class PagedTransactions {
    private final List<String> content;
    private final Map<String, String> links;   // "next", "prev", "self"

    public PagedTransactions(List<String> content, Map<String, String> links) {
        this.content = content;
        this.links = links;
    }
    public List<String> getContent() { return content; }
    public Map<String, String> get_links() { return links; }
}
```

