// ─── File: src/main/java/com/bank/hateoas/controller/TransactionController.java ───
package com.bank.hateoas.controller;

import com.bank.hateoas.dto.PagedTransactions;
import org.springframework.web.bind.annotation.*;
import java.util.List;
import java.util.Map;

// Plain, OpenAPI-documented controller with pragmatic pagination links only.
@RestController
@RequestMapping("/api/v1/accounts/{accountNumber}/transactions")
public class TransactionController {

    @GetMapping
    public PagedTransactions list(@PathVariable String accountNumber,
                                  @RequestParam(defaultValue = "0") int page,
                                  @RequestParam(defaultValue = "20") int size) {
        List<String> content = List.of("TXN-" + (page * size + 1), "TXN-" + (page * size + 2));
        String base = "/api/v1/accounts/" + accountNumber + "/transactions";
        Map<String, String> links = Map.of(
                "self", base + "?page=" + page + "&size=" + size,
                "next", base + "?page=" + (page + 1) + "&size=" + size,
                "prev", base + "?page=" + Math.max(page - 1, 0) + "&size=" + size);
        return new PagedTransactions(content, links);
    }
}
```
